def longest_common_prefix(strings: list[str]) -> str:
    """Return the longest common prefix of a list of strings.

    Args:
        strings: A list of strings to find the common prefix for.

    Returns:
        The longest common prefix string.

    Example:
        >>> longest_common_prefix(['flower', 'flow', 'flight'])
        'fl'
    """
    if not strings:
        return ""
    if len(strings) == 1:
        return strings[0]
    prefix = strings[0]
    for i in range(1, len(strings)):
        prefix = common_prefix(prefix, strings[i])
        if not prefix:
            break
    return prefix


def common_prefix(s1: str, s2: str) -> str:
    """Return the common prefix of two strings."""
    min_len = min(len(s1), len(s2))
    prefix = []
    for i in range(min_len):
        if s1[i] == s2[i]:
            prefix.append(s1[i])
        else:
            break
    return ''.join(prefix)
