def group_dicts_by_key(dicts: list[dict], key: str) -> dict[str, list[dict]]:
    """Group a list of dictionaries by the value of a given key.

    Args:
        dicts: List of dictionaries to group.
        key: The key name to group by.

    Returns:
        A dictionary mapping key values to lists of dictionaries.

    Example:
        >>> group_dicts_by_key(
        ...     [{'a': 1, 'b': 2}, {'a': 2, 'b': 3}, {'a': 1, 'b': 4}],
        ...     'a')
        {'1': [{'a': 1, 'b': 2}, {'a': 1, 'b': 4}], '2': [{'a': 2, 'b': 3}]}
    """
    if not dicts:
        return {}
    groups: dict[str, list[dict]] = {}
    for d in dicts:
        if key not in d:
            raise ValueError(f"Key '{key}' not found in one of the dictionaries.")
        key_value = str(d[key])  # Convert to str to handle non-hashable values
        if key_value not in groups:
            groups[key_value] = []
        groups[key_value].append(d)
    return groups
